int prime[10000001]; // N = 10^7

void sang(){
    for(int i = 0; i <= 10000000; i++) prime[i] = 1;
    prime[0] = prime[1] = 0;
    for(int i = 2; i <= sqrt(10000000); i++){
        if(prime[i]){
            for(int j = i*i; j <= 10000000; j += i)
                prime[j] = 0;
        }
    }
}
// prime[i] == 1  ->  i là số nguyên tố

void sang(ll L, ll R){
    int prime[R - L + 1];
    for(ll i = L; i <= R; i++) prime[i - L] = 1;
    for(ll i = 2; i <= sqrt(R); i++){
        ll start = max(i*i, (L + i - 1) / i * i);
        for(ll j = start; j <= R; j += i)
            prime[j - L] = 0;
    }
    for(ll i = max(2ll, L); i <= R; i++)
        if(prime[i - L]) cout << i << ' ';
}

